public class AgentMetricsCollector
{
    private readonly Counter<long> _tasksCompleted;
    private readonly Counter<long> _tasksFailed;
    private readonly Histogram<double> _stepsPerTask;
    private readonly Histogram<double> _tokensPerTask;
    private readonly Histogram<double> _taskDuration;
    private readonly Histogram<double> _toolCallLatency;

    public AgentMetricsCollector(IMeterFactory meterFactory)
    {
        var meter = meterFactory.Create("EnterpriseNexus.Agent");

        _tasksCompleted = meter.CreateCounter<long>("agent.tasks.completed", "tasks", "Number of completed agent tasks");
        _tasksFailed = meter.CreateCounter<long>("agent.tasks.failed", "tasks", "Number of failed agent tasks");
        _stepsPerTask = meter.CreateHistogram<double>("agent.steps.per_task", "steps", "Average steps per task");
        _tokensPerTask = meter.CreateHistogram<double>("agent.tokens.per_task", "tokens", "Tokens consumed per task");
        _taskDuration = meter.CreateHistogram<double>("agent.task.duration", "seconds", "Task execution duration");
        _toolCallLatency = meter.CreateHistogram<double>("agent.tool.call_latency", "ms", "Tool call latency");
    }

    public void RecordTaskCompletion(bool success, int steps, int totalTokens, TimeSpan duration)
    {
        if (success)
            _tasksCompleted.Add(1);
        else
            _tasksFailed.Add(1);

        _stepsPerTask.Record(steps);
        _tokensPerTask.Record(totalTokens);
        _taskDuration.Record(duration.TotalSeconds);
    }

    public void RecordToolCall(string toolName, TimeSpan duration, bool success)
    {
        _toolCallLatency.Record(duration.TotalMilliseconds, new KeyValuePair<string, object?>("tool_name", toolName));
    }
}

using System.Diagnostics;

public class TracedAgentLoop
{
    private static readonly ActivitySource ActivitySource =
        new ActivitySource("EnterpriseNexus.Agent", "1.0");

    public async Task<string> RunAsync(string userGoal, CancellationToken ct)
    {
        using var activity = ActivitySource.StartActivity("agent.execution");
        activity?.SetTag("gen_ai.system", "openai");
        activity?.SetTag("gen_ai.request.user_agent", "EnterpriseNexus-Agent/1.0");
        activity?.SetTag("session.id", Guid.NewGuid().ToString());

        var conversation = new List<ChatMessage>
        {
            new ChatRole.System, "You are an autonomous agent..."),
            new ChatRole.User, userGoal)
        };

        var stepCount = 0;
        while (stepCount < MaxSteps)
        {
            using var stepActivity = ActivitySource.StartActivity("agent.step");
            stepActivity?.SetTag("agent.step_number", stepCount);

            // LLM call
            using var llmActivity = ActivitySource.StartActivity("llm.completion");
            llmActivity?.SetTag("gen_ai.request.temperature", 0.1);
            llmActivity?.SetTag("gen_ai.request.max_tokens", 4000);

            var completion = await _client.CompleteAsync(conversation, cancellationToken: ct);

            // Tool calls
            var toolCalls = completion.Message.Contents.OfType<FunctionCallContent>().ToList();
            foreach (var call in toolCalls)
            {
                using var toolActivity = ActivitySource.StartActivity("agent.tool_call");
                toolActivity?.SetTag("tool.name", call.Name);
                toolActivity?.SetTag("tool.arguments", JsonSerializer.Serialize(call.Arguments));

                var sw = Stopwatch.StartNew();
                var result = await CallToolAsync(call, ct);
                toolActivity?.SetTag("tool.duration_ms", sw.ElapsedMilliseconds);
                toolActivity?.SetTag("tool.result_length", result?.Length ?? 0);

                conversation.Add(new(ChatRole.Tool, result));
            }

            stepCount++;
        }
        return finalResponse;
    }
}
